class Solution {
    public int findPairs(int[] nums,int k){
        if(k<0)return 0;
        Map<Integer,Integer> counts=new HashMap<>();
        for(int value:nums)counts.put(value,counts.getOrDefault(value,0)+1);
        int answer=0;
        for(Map.Entry<Integer,Integer> entry:counts.entrySet())if(k==0?entry.getValue()>1:counts.containsKey(entry.getKey()+k))answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findPairs(nums:IntArray,k:Int):Int{
        if(k<0)return 0;
        val counts=nums.toList().groupingBy{
            it
        }.eachCount();
        return counts.count{
            (value,count)->if(k==0)count>1 else counts.containsKey(value+k)
        }
    }
}

code.cpp:
class Solution {
    public: int findPairs(vector<int>& nums,int k){
        if(k<0)return 0;
        unordered_map<int,int> counts;
        for(int value:nums)++counts[value];
        int answer=0;
        for(auto [value,count]:counts)if(k==0?count>1:counts.count(value+k))++answer;
        return answer;
    }
};
